fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut seed: i32 = host::display::state_get(1);
    if seed == 0 { seed = 5150; }
    if down == 1 && prev == 0 {
        seed = seed * 1103515245 + 12345;
        host::display::state_set(1, seed);
    }
    host::display::state_set(0, down);
    let cell: i32 = 32;
    let cols: i32 = w / cell;
    let rows: i32 = h / cell;
    host::display::clear(0x08080a);
    let mut r: i32 = 0;
    while r < rows {
        let mut c: i32 = 0;
        while c < cols {
            let x: i32 = c * cell;
            let y: i32 = r * cell;
            let mut cn: i32 = 0;
            let mut ce: i32 = 0;
            if r == 0 && c == cols - 1 {
                cn = 0;
            } else if r == 0 {
                ce = 1;
            } else if c == cols - 1 {
                cn = 1;
            } else {
                let mut hsh: i32 = seed + r * 7919 + c * 104729;
                hsh = hsh * 1103515245 + 12345;
                if ((hsh >> 16) & 1) == 1 { cn = 1; } else { ce = 1; }
            }
            if cn == 0 {
                host::display::draw_line(x, y, x + cell, y, 0xe0e0e8);
            }
            if ce == 0 {
                host::display::draw_line(x + cell, y, x + cell, y + cell, 0xe0e0e8);
            }
            c = c + 1;
        }
        r = r + 1;
    }
    host::display::fill_rect(0, 0, w, 2, 0xe0e0e8);
    host::display::fill_rect(0, h - 2, w, 2, 0xe0e0e8);
    host::display::fill_rect(0, 0, 2, h, 0xe0e0e8);
    host::display::fill_rect(w - 2, 0, 2, h, 0xe0e0e8);
    host::display::present();
}
